import Foundation
func makeNoteRequest() -> URLRequest? {
    let address = "https://api.example.invalid/playlists/9/entries/101"
    guard let url = URL(string: address) else { return nil }
    var request = URLRequest(url: url)
    request.httpMethod = "PATCH"
    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
    request.setValue("application/json", forHTTPHeaderField: "Accept")
    request.httpBody = Data(#"{"note":"Утро"}"#.utf8)
    return request
}
if let request = makeNoteRequest() {
    print(request.httpMethod ?? "")
    print(request.value(forHTTPHeaderField: "Content-Type") ?? "")
}

PATCH передаёт новую note существующей записи по её адресу. Вывод PATCH и application/json; семантика этого JSON согласована учебным API.

import Foundation
func makeReplacePlaylistRequest() -> URLRequest? {
    let address = "https://api.example.invalid/playlists/9"
    guard let url = URL(string: address) else { return nil }
    var request = URLRequest(url: url)
    request.httpMethod = "PUT"
    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
    request.setValue("application/json", forHTTPHeaderField: "Accept")
    request.httpBody = Data(#"{"name":"В дорогу"}"#.utf8)
    return request
}
if let request = makeReplacePlaylistRequest() {
    print(request.httpMethod ?? "")
    print(request.value(forHTTPHeaderField: "Content-Type") ?? "")
}

PUT заменяет изменяемое представление выбранного плейлиста. Вывод PUT и application/json; это не PATCH записи и не POST коллекции.
